:has(dialog[open]) {
    overflow-y: hidden;
}

.side-modal {
    border: $border-width-hairline $border-style-solid $color-gray6;
    @include media('>tablet') {
        position: fixed;
        top: 0;
        right: 0;
        left: auto;
        margin: 0;
        width: 50vw;
        max-width: 90vw;
        height: 100dvh;
        max-height: none;
        overflow-y: auto;
    }
    @include media('<=tablet') {
        width: 100vw;
        height: 90vh;
        max-height: 90vh;
        max-width: 100vw;
        bottom: 0;
        margin-bottom: initial;
        border-top-left-radius: $measure--basic;
        border-top-right-radius: $measure--basic;
    }

    .side-modal__modal__close-btn {
        position: absolute;
        top: $measure--small2;
        right: $measure--small2;
        z-index: 1;

        color: $color-purewhite;
        background-color: $color-nearblack;
        border-radius: $measure--small4;
        width: $measure--small3;
        height: $measure--small3;
    }
}

.side-modal[open] {
    animation: slide-up 300ms ease forwards;
    @include media('>tablet') {
        animation: slide-in 300ms ease forwards;
    }
}

.side-modal[open]::backdrop {
    animation: fade-in 300ms ease forwards;
}

@keyframes fade-in {
    from {
        background: rgba(255, 255, 255, 0);
    }

    to {
        background: rgba(30, 30, 30, 0.3);
    }
}

@include media('reducemotion') {
    .side-modal[open] {
        animation: none;
    }
}

@keyframes slide-in {
    from {
        transform: translateX(100%);
    }

    to {
        transform: translateX(0);
    }
}

@keyframes slide-up {
    from {
        transform: translateY(100%);
    }

    to {
        transform: translateY(0);
    }
}

.courses-v26__modules-details {
    margin-top: $measure--basic;
}

.courses-v26__modules-details__core-label-list {
    display: inline-flex;
}

.courses-v26__modules-details__core-label {
    padding: $measure--quarter $measure--half;
    background-color: $color-brand-primary;
    color: $color-purewhite;
    margin-right: $measure--basic;
}

.js {
    .courses-v26__modules {
        list-style: none;
        margin-left: initial;
        margin-top: initial;
        max-width: initial;

        li {
            @include content-style();
            max-width: initial;
            margin-top: initial;
            display: flex;
            justify-content: space-between;
            padding: $measure--half 0;
            border-bottom: $border-width-hairline $border-style-solid
                $color-gray6;
        }

        .modal__button {
            text-align: left;
        }

        .courses-v26__modules__credits {
            @include content-style();
            @include extrasmalltype();
        }
        .courses-v26__modules-course-loop-url {
            @include content-style();
            @include smalltype();
            max-width: initial;
            justify-content: center;
            width: 100%;
            margin-top: $measure--basic;

            .fa-arrow-right {
                display: flex;
                margin-right: $measure--basic;
                flex-direction: column;
                justify-content: center;
            }

            .courses-v26__modules-course-loop-url__text {
                font-weight: $font-weight-bold;
            }
        }

        .courses-v26__modules-details__year-label {
            @include content-style();
            @include smalltype();
            font-weight: $font-weight-medium;
        }
    }
}

//Course spec ctas
.courses-v26__course-spec-ctas {
    margin-top: initial;
    margin-left: initial;
    list-style: none;
    max-width: initial;
    justify-content: center;
    width: 100%;

    a {
        @include content-style();
        @include anchor-reset();
        @include anchor-border-reset();
        max-width: initial;
        width: 100%;
        font-weight: $font-weight-bold;
        display: flex;
        flex-direction: column;
        padding: $measure--small4;
        color: $color-purewhite;
        background-color: $color-gray8;

        &:hover {
            @include media('hover') {
                background-color: $color-gray8;
                color: $color-purewhite;
            }
        }

        &:visited {
            color: $color-purewhite;
        }
    }

    .fa-arrow-right {
        display: flex;
        margin-right: $measure--basic;
        flex-direction: column;
        justify-content: center;
        margin-bottom: $measure--threequarters;
        @include deltatype();
    }

    .courses-v26__course-spec-cta__text {
        font-weight: $font-weight-bold;
    }
}
